import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { PucOtherDocument } from 'src/app/shared/PucOtherDocument.model';
import { PucOtherDocumentService } from 'src/app/shared/PucOtherDocument.service';

@Component({
  selector: 'app-puc-other-document',
  templateUrl: './puc-other-document.component.html',
  styleUrls: ['./puc-other-document.component.css']
})
export class PucOtherDocumentComponent implements OnInit {

  @ViewChild('PucOtherDocumentSort') PucOtherDocumentSort: MatSort;
  @ViewChild('PucOtherDocumentPaginator') PucOtherDocumentPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public PucOtherDocumentService: PucOtherDocumentService,
  ) { }

  ngOnInit(): void {
  }

  PucOtherDocumentSearch() {
    this.PucOtherDocumentService.SearchAll(this.PucOtherDocumentSort, this.PucOtherDocumentPaginator);
  }
  PucOtherDocumentSave(element: PucOtherDocument) {
    this.PucOtherDocumentService.FormData = element;
    this.NotificationService.warn(this.PucOtherDocumentService.ComponentSaveAll(this.PucOtherDocumentSort, this.PucOtherDocumentPaginator));
  }
  PucOtherDocumentDelete(element: PucOtherDocument) {
    this.PucOtherDocumentService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.PucOtherDocumentService.ComponentDeleteAll(this.PucOtherDocumentSort, this.PucOtherDocumentPaginator));
  }
}
