import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { PucInfoMarkets } from 'src/app/shared/PucInfoMarkets.model';
import { PucInfoMarketsService } from 'src/app/shared/PucInfoMarkets.service';
@Component({
  selector: 'app-puc-info-markets',
  templateUrl: './puc-info-markets.component.html',
  styleUrls: ['./puc-info-markets.component.css']
})
export class PucInfoMarketsComponent implements OnInit {


  @ViewChild('PucInfoMarketsSort') PucInfoMarketsSort: MatSort;
  @ViewChild('PucInfoMarketsPaginator') PucInfoMarketsPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public PucInfoMarketsService: PucInfoMarketsService,
  ) { }

  ngOnInit(): void {
  }

  PucInfoMarketsSearch() {
    this.PucInfoMarketsService.SearchAll(this.PucInfoMarketsSort, this.PucInfoMarketsPaginator);
  }
  PucInfoMarketsSave(element: PucInfoMarkets) {
    this.PucInfoMarketsService.FormData = element;
    this.NotificationService.warn(this.PucInfoMarketsService.ComponentSaveAll(this.PucInfoMarketsSort, this.PucInfoMarketsPaginator));
  }
  PucInfoMarketsDelete(element: PucInfoMarkets) {
    this.PucInfoMarketsService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.PucInfoMarketsService.ComponentDeleteAll(this.PucInfoMarketsSort, this.PucInfoMarketsPaginator));
  }


}
