import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { GSDLBaoCaoNuoiTrong } from 'src/app/shared/GSDLBaoCaoNuoiTrong.model';
import { GSDLBaoCaoNuoiTrongService } from 'src/app/shared/GSDLBaoCaoNuoiTrong.service';
import { GSDLBaoCaoNuoiTrongDetailComponent } from '../gsdlbao-cao-nuoi-trong-detail/gsdlbao-cao-nuoi-trong-detail.component';
@Component({
  selector: 'app-gsdlbao-cao-nuoi-trong',
  templateUrl: './gsdlbao-cao-nuoi-trong.component.html',
  styleUrls: ['./gsdlbao-cao-nuoi-trong.component.css']
})
export class GSDLBaoCaoNuoiTrongComponent implements OnInit {


  @ViewChild('GSDLBaoCaoNuoiTrongSort') GSDLBaoCaoNuoiTrongSort: MatSort;
  @ViewChild('GSDLBaoCaoNuoiTrongPaginator') GSDLBaoCaoNuoiTrongPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public GSDLBaoCaoNuoiTrongService: GSDLBaoCaoNuoiTrongService,
  ) { }

  ngOnInit(): void {
    
  }

  GSDLBaoCaoNuoiTrongSearch() {
    this.GSDLBaoCaoNuoiTrongService.IsShowLoading = true;
    this.GSDLBaoCaoNuoiTrongService.BaseParameter.Active = true;
    this.GSDLBaoCaoNuoiTrongService.GetByyear_number_ActiveToListAsync().subscribe(
      res => {
        this.GSDLBaoCaoNuoiTrongService.List = (res as GSDLBaoCaoNuoiTrong[]).sort((a, b) => (a.SortOrder < b.SortOrder ? 1 : -1));
        this.GSDLBaoCaoNuoiTrongService.DataSource = new MatTableDataSource(this.GSDLBaoCaoNuoiTrongService.List);
        this.GSDLBaoCaoNuoiTrongService.DataSource.sort = this.GSDLBaoCaoNuoiTrongSort;
        this.GSDLBaoCaoNuoiTrongService.DataSource.paginator = this.GSDLBaoCaoNuoiTrongPaginator;
        this.GSDLBaoCaoNuoiTrongService.IsShowLoading = false;
      },
      err => {
        this.GSDLBaoCaoNuoiTrongService.IsShowLoading = false;
      }
    );
  }  
  GSDLBaoCaoNuoiTrongDelete(element: GSDLBaoCaoNuoiTrong) {
    if (confirm(environment.DeleteConfirm)) {
      this.GSDLBaoCaoNuoiTrongService.IsShowLoading = true;
      this.GSDLBaoCaoNuoiTrongService.BaseParameter.ID = element.ID;
      this.GSDLBaoCaoNuoiTrongService.RemoveAsync().subscribe(
        res => {
          this.NotificationService.warn(environment.DeleteSuccess);
          this.GSDLBaoCaoNuoiTrongSearch();
          this.GSDLBaoCaoNuoiTrongService.IsShowLoading = false;
        },
        err => {
          this.NotificationService.warn(environment.DeleteNotSuccess);
          this.GSDLBaoCaoNuoiTrongService.IsShowLoading = false;
        }
      );
    }
  }
  GSDLBaoCaoNuoiTrongAdd(ID: number) {
    this.GSDLBaoCaoNuoiTrongService.IsShowLoading = true;
    this.GSDLBaoCaoNuoiTrongService.BaseParameter.ID = ID;
    this.GSDLBaoCaoNuoiTrongService.GetByIDAsync().subscribe(
      res => {
        this.GSDLBaoCaoNuoiTrongService.FormData = res as GSDLBaoCaoNuoiTrong;        
        const dialogConfig = new MatDialogConfig();
        dialogConfig.disableClose = true;
        dialogConfig.autoFocus = true;
        dialogConfig.width = environment.DialogConfigWidth;
        dialogConfig.data = { ID: ID };
        const dialog = this.dialog.open(GSDLBaoCaoNuoiTrongDetailComponent, dialogConfig);
        dialog.afterClosed().subscribe(() => {
          this.GSDLBaoCaoNuoiTrongSearch();
        });
        this.GSDLBaoCaoNuoiTrongService.IsShowLoading = false;
      },
      err => {
        this.GSDLBaoCaoNuoiTrongService.IsShowLoading = false;
      }
    );
  }
}
