import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { ProductBatchRoutes } from 'src/app/shared/ProductBatchRoutes.model';
import { ProductBatchRoutesService } from 'src/app/shared/ProductBatchRoutes.service';
@Component({
  selector: 'app-product-batch-routes',
  templateUrl: './product-batch-routes.component.html',
  styleUrls: ['./product-batch-routes.component.css']
})
export class ProductBatchRoutesComponent implements OnInit {
  @ViewChild('ProductBatchRoutesSort') ProductBatchRoutesSort: MatSort;
  @ViewChild('ProductBatchRoutesPaginator') ProductBatchRoutesPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public ProductBatchRoutesService: ProductBatchRoutesService,
  ) { }

  ngOnInit(): void {
  }

  ProductBatchRoutesSearch() {
    this.ProductBatchRoutesService.SearchAll(this.ProductBatchRoutesSort, this.ProductBatchRoutesPaginator);
  }
  ProductBatchRoutesSave(element: ProductBatchRoutes) {
    this.ProductBatchRoutesService.FormData = element;
    this.NotificationService.warn(this.ProductBatchRoutesService.ComponentSaveAll(this.ProductBatchRoutesSort, this.ProductBatchRoutesPaginator));
  }
  ProductBatchRoutesDelete(element: ProductBatchRoutes) {
    this.ProductBatchRoutesService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.ProductBatchRoutesService.ComponentDeleteAll(this.ProductBatchRoutesSort, this.ProductBatchRoutesPaginator));
  }


}
