import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { PucInfoFarmers } from 'src/app/shared/PucInfoFarmers.model';
import { PucInfoFarmersService } from 'src/app/shared/PucInfoFarmers.service';
@Component({
  selector: 'app-puc-info-farmers',
  templateUrl: './puc-info-farmers.component.html',
  styleUrls: ['./puc-info-farmers.component.css']
})
export class PucInfoFarmersComponent implements OnInit {

  @ViewChild('PucInfoFarmersSort') PucInfoFarmersSort: MatSort;
  @ViewChild('PucInfoFarmersPaginator') PucInfoFarmersPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public PucInfoFarmersService: PucInfoFarmersService,
  ) { }

  ngOnInit(): void {
  }

  PucInfoFarmersSearch() {
    this.PucInfoFarmersService.SearchAll(this.PucInfoFarmersSort, this.PucInfoFarmersPaginator);
  }
  PucInfoFarmersSave(element: PucInfoFarmers) {
    this.PucInfoFarmersService.FormData = element;
    this.NotificationService.warn(this.PucInfoFarmersService.ComponentSaveAll(this.PucInfoFarmersSort, this.PucInfoFarmersPaginator));
  }
  PucInfoFarmersDelete(element: PucInfoFarmers) {
    this.PucInfoFarmersService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.PucInfoFarmersService.ComponentDeleteAll(this.PucInfoFarmersSort, this.PucInfoFarmersPaginator));
  }


}
