import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { PucDocument } from 'src/app/shared/PucDocument.model';
import { PucDocumentService } from 'src/app/shared/PucDocument.service';
@Component({
  selector: 'app-puc-document',
  templateUrl: './puc-document.component.html',
  styleUrls: ['./puc-document.component.css']
})
export class PucDocumentComponent implements OnInit {

  @ViewChild('PucDocumentSort') PucDocumentSort: MatSort;
  @ViewChild('PucDocumentPaginator') PucDocumentPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public PucDocumentService: PucDocumentService,
  ) { }

  ngOnInit(): void {
  }

  PucDocumentSearch() {
    this.PucDocumentService.SearchAll(this.PucDocumentSort, this.PucDocumentPaginator);
  }
  PucDocumentSave(element: PucDocument) {
    this.PucDocumentService.FormData = element;
    this.NotificationService.warn(this.PucDocumentService.ComponentSaveAll(this.PucDocumentSort, this.PucDocumentPaginator));
  }
  PucDocumentDelete(element: PucDocument) {
    this.PucDocumentService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.PucDocumentService.ComponentDeleteAll(this.PucDocumentSort, this.PucDocumentPaginator));
  }


}
