import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { PackingRegister } from 'src/app/shared/PackingRegister.model';
import { PackingRegisterService } from 'src/app/shared/PackingRegister.service';
@Component({
  selector: 'app-packing-register',
  templateUrl: './packing-register.component.html',
  styleUrls: ['./packing-register.component.css']
})
export class PackingRegisterComponent implements OnInit {

  @ViewChild('PackingRegisterSort') PackingRegisterSort: MatSort;
  @ViewChild('PackingRegisterPaginator') PackingRegisterPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public PackingRegisterService: PackingRegisterService,
  ) { }

  ngOnInit(): void {
  }

  PackingRegisterSearch() {
    this.PackingRegisterService.SearchAll(this.PackingRegisterSort, this.PackingRegisterPaginator);
  }
  PackingRegisterSave(element: PackingRegister) {
    this.PackingRegisterService.FormData = element;
    this.NotificationService.warn(this.PackingRegisterService.ComponentSaveAll(this.PackingRegisterSort, this.PackingRegisterPaginator));
  }
  PackingRegisterDelete(element: PackingRegister) {
    this.PackingRegisterService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.PackingRegisterService.ComponentDeleteAll(this.PackingRegisterSort, this.PackingRegisterPaginator));
  }


}
