import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { PucInfoPucs } from 'src/app/shared/PucInfoPucs.model';
import { PucInfoPucsService } from 'src/app/shared/PucInfoPucs.service';

@Component({
  selector: 'app-puc-info-pucs',
  templateUrl: './puc-info-pucs.component.html',
  styleUrls: ['./puc-info-pucs.component.css']
})
export class PucInfoPucsComponent implements OnInit {


  @ViewChild('PucInfoPucsSort') PucInfoPucsSort: MatSort;
  @ViewChild('PucInfoPucsPaginator') PucInfoPucsPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public PucInfoPucsService: PucInfoPucsService,
  ) { }

  ngOnInit(): void {
  }

  PucInfoPucsSearch() {
    this.PucInfoPucsService.SearchAll(this.PucInfoPucsSort, this.PucInfoPucsPaginator);
  }
  PucInfoPucsSave(element: PucInfoPucs) {
    this.PucInfoPucsService.FormData = element;
    this.NotificationService.warn(this.PucInfoPucsService.ComponentSaveAll(this.PucInfoPucsSort, this.PucInfoPucsPaginator));
  }
  PucInfoPucsDelete(element: PucInfoPucs) {
    this.PucInfoPucsService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.PucInfoPucsService.ComponentDeleteAll(this.PucInfoPucsSort, this.PucInfoPucsPaginator));
  }


}
