import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { PucRegisterLog } from 'src/app/shared/PucRegisterLog.model';
import { PucRegisterLogService } from 'src/app/shared/PucRegisterLog.service';

@Component({
  selector: 'app-puc-register-log',
  templateUrl: './puc-register-log.component.html',
  styleUrls: ['./puc-register-log.component.css']
})

export class PucRegisterLogComponent implements OnInit {

  @ViewChild('PucRegisterLogSort') PucRegisterLogSort: MatSort;
  @ViewChild('PucRegisterLogPaginator') PucRegisterLogPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public PucRegisterLogService: PucRegisterLogService,
  ) { }

  ngOnInit(): void {
  }

  PucRegisterLogSearch() {
    this.PucRegisterLogService.SearchAll(this.PucRegisterLogSort, this.PucRegisterLogPaginator);
  }
  PucRegisterLogSave(element: PucRegisterLog) {
    this.PucRegisterLogService.FormData = element;
    this.NotificationService.warn(this.PucRegisterLogService.ComponentSaveAll(this.PucRegisterLogSort, this.PucRegisterLogPaginator));
  }
  PucRegisterLogDelete(element: PucRegisterLog) {
    this.PucRegisterLogService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.PucRegisterLogService.ComponentDeleteAll(this.PucRegisterLogSort, this.PucRegisterLogPaginator));
  }
}
