import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { NT2MVPlan } from 'src/app/shared/NT2MVPlan.model';
import { NT2MVPlanService } from 'src/app/shared/NT2MVPlan.service';
@Component({
  selector: 'app-nt2-mvplan',
  templateUrl: './nt2-mvplan.component.html',
  styleUrls: ['./nt2-mvplan.component.css']
})
export class NT2MVPlanComponent implements OnInit {

  @ViewChild('NT2MVPlanSort') NT2MVPlanSort: MatSort;
  @ViewChild('NT2MVPlanPaginator') NT2MVPlanPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public NT2MVPlanService: NT2MVPlanService,
  ) { }

  ngOnInit(): void {
  }

  NT2MVPlanSearch() {
    this.NT2MVPlanService.SearchAll(this.NT2MVPlanSort, this.NT2MVPlanPaginator);
  }
  NT2MVPlanSave(element: NT2MVPlan) {
    this.NT2MVPlanService.FormData = element;
    this.NotificationService.warn(this.NT2MVPlanService.ComponentSaveAll(this.NT2MVPlanSort, this.NT2MVPlanPaginator));
  }
  NT2MVPlanDelete(element: NT2MVPlan) {
    this.NT2MVPlanService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.NT2MVPlanService.ComponentDeleteAll(this.NT2MVPlanSort, this.NT2MVPlanPaginator));
  }


}
