import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { PackingRegisterPacks } from 'src/app/shared/PackingRegisterPacks.model';
import { PackingRegisterPacksService } from 'src/app/shared/PackingRegisterPacks.service';
@Component({
  selector: 'app-packing-register-packs',
  templateUrl: './packing-register-packs.component.html',
  styleUrls: ['./packing-register-packs.component.css']
})
export class PackingRegisterPacksComponent implements OnInit {

  @ViewChild('PackingRegisterPacksSort') PackingRegisterPacksSort: MatSort;
  @ViewChild('PackingRegisterPacksPaginator') PackingRegisterPacksPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public PackingRegisterPacksService: PackingRegisterPacksService,
  ) { }

  ngOnInit(): void {
  }

  PackingRegisterPacksSearch() {
    this.PackingRegisterPacksService.SearchAll(this.PackingRegisterPacksSort, this.PackingRegisterPacksPaginator);
  }
  PackingRegisterPacksSave(element: PackingRegisterPacks) {
    this.PackingRegisterPacksService.FormData = element;
    this.NotificationService.warn(this.PackingRegisterPacksService.ComponentSaveAll(this.PackingRegisterPacksSort, this.PackingRegisterPacksPaginator));
  }
  PackingRegisterPacksDelete(element: PackingRegisterPacks) {
    this.PackingRegisterPacksService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.PackingRegisterPacksService.ComponentDeleteAll(this.PackingRegisterPacksSort, this.PackingRegisterPacksPaginator));
  }


}
