
import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { KiemTraTapChat } from 'src/app/shared/KiemTraTapChat.model';
import { KiemTraTapChatService } from 'src/app/shared/KiemTraTapChat.service';
@Component({
  selector: 'app-kiem-tra-tap-chat',
  templateUrl: './kiem-tra-tap-chat.component.html',
  styleUrls: ['./kiem-tra-tap-chat.component.css']
})
export class KiemTraTapChatComponent implements OnInit {

  @ViewChild('KiemTraTapChatSort') KiemTraTapChatSort: MatSort;
  @ViewChild('KiemTraTapChatPaginator') KiemTraTapChatPaginator: MatPaginator;
  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public KiemTraTapChatService: KiemTraTapChatService,
  ) { }

  ngOnInit(): void {
  }

  KiemTraTapChatSearch() {
    this.KiemTraTapChatService.SearchAll(this.KiemTraTapChatSort, this.KiemTraTapChatPaginator);
  }
  KiemTraTapChatSave(element: KiemTraTapChat) {
    this.KiemTraTapChatService.FormData = element;
    this.NotificationService.warn(this.KiemTraTapChatService.ComponentSaveAll(this.KiemTraTapChatSort, this.KiemTraTapChatPaginator));
  }
  KiemTraTapChatDelete(element: KiemTraTapChat) {
    this.KiemTraTapChatService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.KiemTraTapChatService.ComponentDeleteAll(this.KiemTraTapChatSort, this.KiemTraTapChatPaginator));
  }


}

