import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { ProductBatchGeocodedWaypoints } from 'src/app/shared/ProductBatchGeocodedWaypoints.model';
import { ProductBatchGeocodedWaypointsService } from 'src/app/shared/ProductBatchGeocodedWaypoints.service';

@Component({
  selector: 'app-product-batch-geocoded-waypoints',
  templateUrl: './product-batch-geocoded-waypoints.component.html',
  styleUrls: ['./product-batch-geocoded-waypoints.component.css']
})
export class ProductBatchGeocodedWaypointsComponent implements OnInit {


  @ViewChild('ProductBatchGeocodedWaypointsSort') ProductBatchGeocodedWaypointsSort: MatSort;
  @ViewChild('ProductBatchGeocodedWaypointsPaginator') ProductBatchGeocodedWaypointsPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public ProductBatchGeocodedWaypointsService: ProductBatchGeocodedWaypointsService,
  ) { }

  ngOnInit(): void {
  }

  ProductBatchGeocodedWaypointsSearch() {
    this.ProductBatchGeocodedWaypointsService.SearchAll(this.ProductBatchGeocodedWaypointsSort, this.ProductBatchGeocodedWaypointsPaginator);
  }
  ProductBatchGeocodedWaypointsSave(element: ProductBatchGeocodedWaypoints) {
    this.ProductBatchGeocodedWaypointsService.FormData = element;
    this.NotificationService.warn(this.ProductBatchGeocodedWaypointsService.ComponentSaveAll(this.ProductBatchGeocodedWaypointsSort, this.ProductBatchGeocodedWaypointsPaginator));
  }
  ProductBatchGeocodedWaypointsDelete(element: ProductBatchGeocodedWaypoints) {
    this.ProductBatchGeocodedWaypointsService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.ProductBatchGeocodedWaypointsService.ComponentDeleteAll(this.ProductBatchGeocodedWaypointsSort, this.ProductBatchGeocodedWaypointsPaginator));
  }


}
