import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { DiaryInfo } from 'src/app/shared/DiaryInfo.model';
import { DiaryInfoService } from 'src/app/shared/DiaryInfo.service';
@Component({
  selector: 'app-diary-info',
  templateUrl: './diary-info.component.html',
  styleUrls: ['./diary-info.component.css']
})
export class DiaryInfoComponent implements OnInit {

  @ViewChild('DiaryInfoSort') DiaryInfoSort: MatSort;
  @ViewChild('DiaryInfoPaginator') DiaryInfoPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public DiaryInfoService: DiaryInfoService,
  ) { }

  ngOnInit(): void {
  }

  DiaryInfoSearch() {
    this.DiaryInfoService.SearchAll(this.DiaryInfoSort, this.DiaryInfoPaginator);
  }
  DiaryInfoSave(element: DiaryInfo) {
    this.DiaryInfoService.FormData = element;
    this.NotificationService.warn(this.DiaryInfoService.ComponentSaveAll(this.DiaryInfoSort, this.DiaryInfoPaginator));
  }
  DiaryInfoDelete(element: DiaryInfo) {
    this.DiaryInfoService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.DiaryInfoService.ComponentDeleteAll(this.DiaryInfoSort, this.DiaryInfoPaginator));
  }


}
