import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';

import { ThamDinhCompanyDocuments } from 'src/app/shared/ThamDinhCompanyDocuments.model';
import { ThamDinhCompanyDocumentsService } from 'src/app/shared/ThamDinhCompanyDocuments.service';
@Component({
  selector: 'app-tham-dinh-company-documents',
  templateUrl: './tham-dinh-company-documents.component.html',
  styleUrls: ['./tham-dinh-company-documents.component.css']
})
export class ThamDinhCompanyDocumentsComponent implements OnInit {

  @ViewChild('ThamDinhCompanyDocumentsSort') ThamDinhCompanyDocumentsSort: MatSort;
  @ViewChild('ThamDinhCompanyDocumentsPaginator') ThamDinhCompanyDocumentsPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public ThamDinhCompanyDocumentsService: ThamDinhCompanyDocumentsService,
  ) { }

  ngOnInit(): void {
  }

  ThamDinhCompanyDocumentsSearch() {
    this.ThamDinhCompanyDocumentsService.SearchAll(this.ThamDinhCompanyDocumentsSort, this.ThamDinhCompanyDocumentsPaginator);
  }
  ThamDinhCompanyDocumentsSave(element: ThamDinhCompanyDocuments) {
    this.ThamDinhCompanyDocumentsService.FormData = element;
    this.NotificationService.warn(this.ThamDinhCompanyDocumentsService.ComponentSaveAll(this.ThamDinhCompanyDocumentsSort, this.ThamDinhCompanyDocumentsPaginator));
  }
  ThamDinhCompanyDocumentsDelete(element: ThamDinhCompanyDocuments) {
    this.ThamDinhCompanyDocumentsService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.ThamDinhCompanyDocumentsService.ComponentDeleteAll(this.ThamDinhCompanyDocumentsSort, this.ThamDinhCompanyDocumentsPaginator));
  }
}
