import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { PackRegisterLog } from 'src/app/shared/PackRegisterLog.model';
import { PackRegisterLogService } from 'src/app/shared/PackRegisterLog.service';
@Component({
  selector: 'app-pack-register-log',
  templateUrl: './pack-register-log.component.html',
  styleUrls: ['./pack-register-log.component.css']
})
export class PackRegisterLogComponent implements OnInit {
  @ViewChild('PackRegisterLogSort') PackRegisterLogSort: MatSort;
  @ViewChild('PackRegisterLogPaginator') PackRegisterLogPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public PackRegisterLogService: PackRegisterLogService,
  ) { }

  ngOnInit(): void {
  }

  PackRegisterLogSearch() {
    this.PackRegisterLogService.SearchAll(this.PackRegisterLogSort, this.PackRegisterLogPaginator);
  }
  PackRegisterLogSave(element: PackRegisterLog) {
    this.PackRegisterLogService.FormData = element;
    this.NotificationService.warn(this.PackRegisterLogService.ComponentSaveAll(this.PackRegisterLogSort, this.PackRegisterLogPaginator));
  }
  PackRegisterLogDelete(element: PackRegisterLog) {
    this.PackRegisterLogService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.PackRegisterLogService.ComponentDeleteAll(this.PackRegisterLogSort, this.PackRegisterLogPaginator));
  }


}
