
import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';

import { ThuMuaNongSan } from 'src/app/shared/ThuMuaNongSan.model';
import { ThuMuaNongSanService } from 'src/app/shared/ThuMuaNongSan.service';

@Component({
  selector: 'app-thu-mua-nong-san',
  templateUrl: './thu-mua-nong-san.component.html',
  styleUrls: ['./thu-mua-nong-san.component.css']
})
export class ThuMuaNongSanComponent implements OnInit {
  @ViewChild('ThuMuaNongSanSort') ThuMuaNongSanSort: MatSort;
  @ViewChild('ThuMuaNongSanPaginator') ThuMuaNongSanPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public ThuMuaNongSanService: ThuMuaNongSanService,
  ) { }

  ngOnInit(): void {
  }

  ThuMuaNongSanSearch() {
    this.ThuMuaNongSanService.SearchAll(this.ThuMuaNongSanSort, this.ThuMuaNongSanPaginator);
  }
  ThuMuaNongSanSave(element: ThuMuaNongSan) {
    this.ThuMuaNongSanService.FormData = element;
    this.NotificationService.warn(this.ThuMuaNongSanService.ComponentSaveAll(this.ThuMuaNongSanSort, this.ThuMuaNongSanPaginator));
  }
  ThuMuaNongSanDelete(element: ThuMuaNongSan) {
    this.ThuMuaNongSanService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.ThuMuaNongSanService.ComponentDeleteAll(this.ThuMuaNongSanSort, this.ThuMuaNongSanPaginator));
  }
}
