import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';

import { ViolateInfo } from 'src/app/shared/ViolateInfo.model';
import { ViolateInfoService } from 'src/app/shared/ViolateInfo.service';

@Component({
  selector: 'app-violate-info',
  templateUrl: './violate-info.component.html',
  styleUrls: ['./violate-info.component.css']
})
export class ViolateInfoComponent implements OnInit {
  @ViewChild('ViolateInfoSort') ViolateInfoSort: MatSort;
  @ViewChild('ViolateInfoPaginator') ViolateInfoPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public ViolateInfoService: ViolateInfoService,
  ) { }

  ngOnInit(): void {
  }

  ViolateInfoSearch() {
    this.ViolateInfoService.SearchAll(this.ViolateInfoSort, this.ViolateInfoPaginator);
  }
  ViolateInfoSave(element: ViolateInfo) {
    this.ViolateInfoService.FormData = element;
    this.NotificationService.warn(this.ViolateInfoService.ComponentSaveAll(this.ViolateInfoSort, this.ViolateInfoPaginator));
  }
  ViolateInfoDelete(element: ViolateInfo) {
    this.ViolateInfoService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.ViolateInfoService.ComponentDeleteAll(this.ViolateInfoSort, this.ViolateInfoPaginator));
  }
}
