import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';

import { ThamDinhCompany } from 'src/app/shared/ThamDinhCompany.model';
import { ThamDinhCompanyService } from 'src/app/shared/ThamDinhCompany.service';
@Component({
  selector: 'app-tham-dinh-company',
  templateUrl: './tham-dinh-company.component.html',
  styleUrls: ['./tham-dinh-company.component.css']
})
export class ThamDinhCompanyComponent implements OnInit {

  @ViewChild('ThamDinhCompanySort') ThamDinhCompanySort: MatSort;
  @ViewChild('ThamDinhCompanyPaginator') ThamDinhCompanyPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public ThamDinhCompanyService: ThamDinhCompanyService,
  ) { }

  ngOnInit(): void {
  }

  ThamDinhCompanySearch() {
    this.ThamDinhCompanyService.SearchAll(this.ThamDinhCompanySort, this.ThamDinhCompanyPaginator);
  }
  ThamDinhCompanySave(element: ThamDinhCompany) {
    this.ThamDinhCompanyService.FormData = element;
    this.NotificationService.warn(this.ThamDinhCompanyService.ComponentSaveAll(this.ThamDinhCompanySort, this.ThamDinhCompanyPaginator));
  }
  ThamDinhCompanyDelete(element: ThamDinhCompany) {
    this.ThamDinhCompanyService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.ThamDinhCompanyService.ComponentDeleteAll(this.ThamDinhCompanySort, this.ThamDinhCompanyPaginator));
  }
}
