import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { PartnerCompany } from 'src/app/shared/PartnerCompany.model';
import { PartnerCompanyService } from 'src/app/shared/PartnerCompany.service';
@Component({
  selector: 'app-partner-company',
  templateUrl: './partner-company.component.html',
  styleUrls: ['./partner-company.component.css']
})
export class PartnerCompanyComponent implements OnInit {
  @ViewChild('PartnerCompanySort') PartnerCompanySort: MatSort;
  @ViewChild('PartnerCompanyPaginator') PartnerCompanyPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public PartnerCompanyService: PartnerCompanyService,
  ) { }

  ngOnInit(): void {
  }

  PartnerCompanySearch() {
    this.PartnerCompanyService.SearchAll(this.PartnerCompanySort, this.PartnerCompanyPaginator);
  }
  PartnerCompanySave(element: PartnerCompany) {
    this.PartnerCompanyService.FormData = element;
    this.NotificationService.warn(this.PartnerCompanyService.ComponentSaveAll(this.PartnerCompanySort, this.PartnerCompanyPaginator));
  }
  PartnerCompanyDelete(element: PartnerCompany) {
    this.PartnerCompanyService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.PartnerCompanyService.ComponentDeleteAll(this.PartnerCompanySort, this.PartnerCompanyPaginator));
  }


}
