import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { ProductBatch } from 'src/app/shared/ProductBatch.model';
import { ProductBatchService } from 'src/app/shared/ProductBatch.service';
@Component({
  selector: 'app-product-batch',
  templateUrl: './product-batch.component.html',
  styleUrls: ['./product-batch.component.css']
})
export class ProductBatchComponent implements OnInit {


  @ViewChild('ProductBatchSort') ProductBatchSort: MatSort;
  @ViewChild('ProductBatchPaginator') ProductBatchPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public ProductBatchService: ProductBatchService,
  ) { }

  ngOnInit(): void {
  }

  ProductBatchSearch() {
    this.ProductBatchService.SearchAll(this.ProductBatchSort, this.ProductBatchPaginator);
  }
  ProductBatchSave(element: ProductBatch) {
    this.ProductBatchService.FormData = element;
    this.NotificationService.warn(this.ProductBatchService.ComponentSaveAll(this.ProductBatchSort, this.ProductBatchPaginator));
  }
  ProductBatchDelete(element: ProductBatch) {
    this.ProductBatchService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.ProductBatchService.ComponentDeleteAll(this.ProductBatchSort, this.ProductBatchPaginator));
  }


}
