import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { ChuoiCungUngPlanDetail } from 'src/app/shared/ChuoiCungUngPlanDetail.model';
import { ChuoiCungUngPlanDetailService } from 'src/app/shared/ChuoiCungUngPlanDetail.service';
@Component({
  selector: 'app-chuoi-cung-ung-plan-detail',
  templateUrl: './chuoi-cung-ung-plan-detail.component.html',
  styleUrls: ['./chuoi-cung-ung-plan-detail.component.css']
})
export class ChuoiCungUngPlanDetailComponent implements OnInit {

  @ViewChild('ChuoiCungUngPlanDetailSort') ChuoiCungUngPlanDetailSort: MatSort;
  @ViewChild('ChuoiCungUngPlanDetailPaginator') ChuoiCungUngPlanDetailPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public ChuoiCungUngPlanDetailService: ChuoiCungUngPlanDetailService,
  ) { }

  ngOnInit(): void {
  }

  ChuoiCungUngPlanDetailSearch() {
    this.ChuoiCungUngPlanDetailService.SearchAll(this.ChuoiCungUngPlanDetailSort, this.ChuoiCungUngPlanDetailPaginator);
  }
  ChuoiCungUngPlanDetailSave(element: ChuoiCungUngPlanDetail) {
    this.ChuoiCungUngPlanDetailService.FormData = element;
    this.NotificationService.warn(this.ChuoiCungUngPlanDetailService.ComponentSaveAll(this.ChuoiCungUngPlanDetailSort, this.ChuoiCungUngPlanDetailPaginator));
  }
  ChuoiCungUngPlanDetailDelete(element: ChuoiCungUngPlanDetail) {
    this.ChuoiCungUngPlanDetailService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.ChuoiCungUngPlanDetailService.ComponentDeleteAll(this.ChuoiCungUngPlanDetailSort, this.ChuoiCungUngPlanDetailPaginator));
  }


}
