import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { ProductBatchImages } from 'src/app/shared/ProductBatchImages.model';
import { ProductBatchImagesService } from 'src/app/shared/ProductBatchImages.service';
@Component({
  selector: 'app-product-batch-images',
  templateUrl: './product-batch-images.component.html',
  styleUrls: ['./product-batch-images.component.css']
})
export class ProductBatchImagesComponent implements OnInit {
  @ViewChild('ProductBatchImagesSort') ProductBatchImagesSort: MatSort;
  @ViewChild('ProductBatchImagesPaginator') ProductBatchImagesPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public ProductBatchImagesService: ProductBatchImagesService,
  ) { }

  ngOnInit(): void {
  }

  ProductBatchImagesSearch() {
    this.ProductBatchImagesService.SearchAll(this.ProductBatchImagesSort, this.ProductBatchImagesPaginator);
  }
  ProductBatchImagesSave(element: ProductBatchImages) {
    this.ProductBatchImagesService.FormData = element;
    this.NotificationService.warn(this.ProductBatchImagesService.ComponentSaveAll(this.ProductBatchImagesSort, this.ProductBatchImagesPaginator));
  }
  ProductBatchImagesDelete(element: ProductBatchImages) {
    this.ProductBatchImagesService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.ProductBatchImagesService.ComponentDeleteAll(this.ProductBatchImagesSort, this.ProductBatchImagesPaginator));
  }


}
