import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { ProductBatchBuyerLocation } from 'src/app/shared/ProductBatchBuyerLocation.model';
import { ProductBatchBuyerLocationService } from 'src/app/shared/ProductBatchBuyerLocation.service';
@Component({
  selector: 'app-product-batch-buyer-location',
  templateUrl: './product-batch-buyer-location.component.html',
  styleUrls: ['./product-batch-buyer-location.component.css']
})
export class ProductBatchBuyerLocationComponent implements OnInit {

  @ViewChild('ProductBatchBuyerLocationSort') ProductBatchBuyerLocationSort: MatSort;
  @ViewChild('ProductBatchBuyerLocationPaginator') ProductBatchBuyerLocationPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public ProductBatchBuyerLocationService: ProductBatchBuyerLocationService,
  ) { }

  ngOnInit(): void {
  }

  ProductBatchBuyerLocationSearch() {
    this.ProductBatchBuyerLocationService.SearchAll(this.ProductBatchBuyerLocationSort, this.ProductBatchBuyerLocationPaginator);
  }
  ProductBatchBuyerLocationSave(element: ProductBatchBuyerLocation) {
    this.ProductBatchBuyerLocationService.FormData = element;
    this.NotificationService.warn(this.ProductBatchBuyerLocationService.ComponentSaveAll(this.ProductBatchBuyerLocationSort, this.ProductBatchBuyerLocationPaginator));
  }
  ProductBatchBuyerLocationDelete(element: ProductBatchBuyerLocation) {
    this.ProductBatchBuyerLocationService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.ProductBatchBuyerLocationService.ComponentDeleteAll(this.ProductBatchBuyerLocationSort, this.ProductBatchBuyerLocationPaginator));
  }


}
