import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { ProductBatchTem } from 'src/app/shared/ProductBatchTem.model';
import { ProductBatchTemService } from 'src/app/shared/ProductBatchTem.service';
@Component({
  selector: 'app-product-batch-tem',
  templateUrl: './product-batch-tem.component.html',
  styleUrls: ['./product-batch-tem.component.css']
})
export class ProductBatchTemComponent implements OnInit {

  @ViewChild('ProductBatchTemSort') ProductBatchTemSort: MatSort;
  @ViewChild('ProductBatchTemPaginator') ProductBatchTemPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public ProductBatchTemService: ProductBatchTemService,
  ) { }

  ngOnInit(): void {
  }

  ProductBatchTemSearch() {
    this.ProductBatchTemService.SearchAll(this.ProductBatchTemSort, this.ProductBatchTemPaginator);
  }
  ProductBatchTemSave(element: ProductBatchTem) {
    this.ProductBatchTemService.FormData = element;
    this.NotificationService.warn(this.ProductBatchTemService.ComponentSaveAll(this.ProductBatchTemSort, this.ProductBatchTemPaginator));
  }
  ProductBatchTemDelete(element: ProductBatchTem) {
    this.ProductBatchTemService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.ProductBatchTemService.ComponentDeleteAll(this.ProductBatchTemSort, this.ProductBatchTemPaginator));
  }


}
