import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { GiamSatDuLuongPlan } from 'src/app/shared/GiamSatDuLuongPlan.model';
import { GiamSatDuLuongPlanService } from 'src/app/shared/GiamSatDuLuongPlan.service';
@Component({
  selector: 'app-giam-sat-du-luong-plan',
  templateUrl: './giam-sat-du-luong-plan.component.html',
  styleUrls: ['./giam-sat-du-luong-plan.component.css']
})
export class GiamSatDuLuongPlanComponent implements OnInit {

  @ViewChild('GiamSatDuLuongPlanSort') GiamSatDuLuongPlanSort: MatSort;
  @ViewChild('GiamSatDuLuongPlanPaginator') GiamSatDuLuongPlanPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public GiamSatDuLuongPlanService: GiamSatDuLuongPlanService,
  ) { }

  ngOnInit(): void {
  }

  GiamSatDuLuongPlanSearch() {
    this.GiamSatDuLuongPlanService.SearchAll(this.GiamSatDuLuongPlanSort, this.GiamSatDuLuongPlanPaginator);
  }
  GiamSatDuLuongPlanSave(element: GiamSatDuLuongPlan) {
    this.GiamSatDuLuongPlanService.FormData = element;
    this.NotificationService.warn(this.GiamSatDuLuongPlanService.ComponentSaveAll(this.GiamSatDuLuongPlanSort, this.GiamSatDuLuongPlanPaginator));
  }
  GiamSatDuLuongPlanDelete(element: GiamSatDuLuongPlan) {
    this.GiamSatDuLuongPlanService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.GiamSatDuLuongPlanService.ComponentDeleteAll(this.GiamSatDuLuongPlanSort, this.GiamSatDuLuongPlanPaginator));
  }


}
