import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { PackingRegisterPacksPucs } from 'src/app/shared/PackingRegisterPacksPucs.model';
import { PackingRegisterPacksPucsService } from 'src/app/shared/PackingRegisterPacksPucs.service';
@Component({
  selector: 'app-packing-register-packs-pucs',
  templateUrl: './packing-register-packs-pucs.component.html',
  styleUrls: ['./packing-register-packs-pucs.component.css']
})
export class PackingRegisterPacksPucsComponent implements OnInit {
  @ViewChild('PackingRegisterPacksPucsSort') PackingRegisterPacksPucsSort: MatSort;
  @ViewChild('PackingRegisterPacksPucsPaginator') PackingRegisterPacksPucsPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public PackingRegisterPacksPucsService: PackingRegisterPacksPucsService,
  ) { }

  ngOnInit(): void {
  }

  PackingRegisterPacksPucsSearch() {
    this.PackingRegisterPacksPucsService.SearchAll(this.PackingRegisterPacksPucsSort, this.PackingRegisterPacksPucsPaginator);
  }
  PackingRegisterPacksPucsSave(element: PackingRegisterPacksPucs) {
    this.PackingRegisterPacksPucsService.FormData = element;
    this.NotificationService.warn(this.PackingRegisterPacksPucsService.ComponentSaveAll(this.PackingRegisterPacksPucsSort, this.PackingRegisterPacksPucsPaginator));
  }
  PackingRegisterPacksPucsDelete(element: PackingRegisterPacksPucs) {
    this.PackingRegisterPacksPucsService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.PackingRegisterPacksPucsService.ComponentDeleteAll(this.PackingRegisterPacksPucsSort, this.PackingRegisterPacksPucsPaginator));
  }


}
