import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { PucInfoMaps } from 'src/app/shared/PucInfoMaps.model';
import { PucInfoMapsService } from 'src/app/shared/PucInfoMaps.service';
@Component({
  selector: 'app-puc-info-maps',
  templateUrl: './puc-info-maps.component.html',
  styleUrls: ['./puc-info-maps.component.css']
})
export class PucInfoMapsComponent implements OnInit {

  @ViewChild('PucInfoMapsSort') PucInfoMapsSort: MatSort;
  @ViewChild('PucInfoMapsPaginator') PucInfoMapsPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public PucInfoMapsService: PucInfoMapsService,
  ) { }

  ngOnInit(): void {
  }

  PucInfoMapsSearch() {
    this.PucInfoMapsService.SearchAll(this.PucInfoMapsSort, this.PucInfoMapsPaginator);
  }
  PucInfoMapsSave(element: PucInfoMaps) {
    this.PucInfoMapsService.FormData = element;
    this.NotificationService.warn(this.PucInfoMapsService.ComponentSaveAll(this.PucInfoMapsSort, this.PucInfoMapsPaginator));
  }
  PucInfoMapsDelete(element: PucInfoMaps) {
    this.PucInfoMapsService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.PucInfoMapsService.ComponentDeleteAll(this.PucInfoMapsSort, this.PucInfoMapsPaginator));
  }


}
