import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { BienBanCSDGResults } from 'src/app/shared/BienBanCSDGResults.model';
import { BienBanCSDGResultsService } from 'src/app/shared/BienBanCSDGResults.service';
@Component({
  selector: 'app-bien-ban-csdgresults',
  templateUrl: './bien-ban-csdgresults.component.html',
  styleUrls: ['./bien-ban-csdgresults.component.css']
})
export class BienBanCSDGResultsComponent implements OnInit {

  @ViewChild('BienBanCSDGResultsSort') BienBanCSDGResultsSort: MatSort;
  @ViewChild('BienBanCSDGResultsPaginator') BienBanCSDGResultsPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public BienBanCSDGResultsService: BienBanCSDGResultsService,
  ) { }

  ngOnInit(): void {
  }

  BienBanCSDGResultsSearch() {
    this.BienBanCSDGResultsService.SearchAll(this.BienBanCSDGResultsSort, this.BienBanCSDGResultsPaginator);
  }
  BienBanCSDGResultsSave(element: BienBanCSDGResults) {
    this.BienBanCSDGResultsService.FormData = element;
    this.NotificationService.warn(this.BienBanCSDGResultsService.ComponentSaveAll(this.BienBanCSDGResultsSort, this.BienBanCSDGResultsPaginator));
  }
  BienBanCSDGResultsDelete(element: BienBanCSDGResults) {
    this.BienBanCSDGResultsService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.BienBanCSDGResultsService.ComponentDeleteAll(this.BienBanCSDGResultsSort, this.BienBanCSDGResultsPaginator));
  }


}
