import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { BienBanMSVTResults } from 'src/app/shared/BienBanMSVTResults.model';
import { BienBanMSVTResultsService } from 'src/app/shared/BienBanMSVTResults.service';
@Component({
  selector: 'app-bien-ban-msvtresults',
  templateUrl: './bien-ban-msvtresults.component.html',
  styleUrls: ['./bien-ban-msvtresults.component.css']
})
export class BienBanMSVTResultsComponent implements OnInit {


  @ViewChild('BienBanMSVTResultsSort') BienBanMSVTResultsSort: MatSort;
  @ViewChild('BienBanMSVTResultsPaginator') BienBanMSVTResultsPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public BienBanMSVTResultsService: BienBanMSVTResultsService,
  ) { }

  ngOnInit(): void {
  }

  BienBanMSVTResultsSearch() {
    this.BienBanMSVTResultsService.SearchAll(this.BienBanMSVTResultsSort, this.BienBanMSVTResultsPaginator);
  }
  BienBanMSVTResultsSave(element: BienBanMSVTResults) {
    this.BienBanMSVTResultsService.FormData = element;
    this.NotificationService.warn(this.BienBanMSVTResultsService.ComponentSaveAll(this.BienBanMSVTResultsSort, this.BienBanMSVTResultsPaginator));
  }
  BienBanMSVTResultsDelete(element: BienBanMSVTResults) {
    this.BienBanMSVTResultsService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.BienBanMSVTResultsService.ComponentDeleteAll(this.BienBanMSVTResultsSort, this.BienBanMSVTResultsPaginator));
  }


}
