import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { PackingRegisterStaffs } from 'src/app/shared/PackingRegisterStaffs.model';
import { PackingRegisterStaffsService } from 'src/app/shared/PackingRegisterStaffs.service';
@Component({
  selector: 'app-packing-register-staffs',
  templateUrl: './packing-register-staffs.component.html',
  styleUrls: ['./packing-register-staffs.component.css']
})
export class PackingRegisterStaffsComponent implements OnInit {
  @ViewChild('PackingRegisterStaffsSort') PackingRegisterStaffsSort: MatSort;
  @ViewChild('PackingRegisterStaffsPaginator') PackingRegisterStaffsPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public PackingRegisterStaffsService: PackingRegisterStaffsService,
  ) { }

  ngOnInit(): void {
  }

  PackingRegisterStaffsSearch() {
    this.PackingRegisterStaffsService.SearchAll(this.PackingRegisterStaffsSort, this.PackingRegisterStaffsPaginator);
  }
  PackingRegisterStaffsSave(element: PackingRegisterStaffs) {
    this.PackingRegisterStaffsService.FormData = element;
    this.NotificationService.warn(this.PackingRegisterStaffsService.ComponentSaveAll(this.PackingRegisterStaffsSort, this.PackingRegisterStaffsPaginator));
  }
  PackingRegisterStaffsDelete(element: PackingRegisterStaffs) {
    this.PackingRegisterStaffsService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.PackingRegisterStaffsService.ComponentDeleteAll(this.PackingRegisterStaffsSort, this.PackingRegisterStaffsPaginator));
  }


}
