import { Component, OnInit, Inject, ElementRef, ViewChild } from '@angular/core';
import { NgForm } from '@angular/forms';
import { environment } from 'src/environments/environment';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { MatDialogRef, MAT_DIALOG_DATA } from '@angular/material/dialog';
import { NotificationService } from 'src/app/shared/Notification.service';


import { GSDLBaoCaoNuoiTrong } from 'src/app/shared/GSDLBaoCaoNuoiTrong.model';
import { GSDLBaoCaoNuoiTrongService } from 'src/app/shared/GSDLBaoCaoNuoiTrong.service';

@Component({
  selector: 'app-gsdlbao-cao-nuoi-trong-detail',
  templateUrl: './gsdlbao-cao-nuoi-trong-detail.component.html',
  styleUrls: ['./gsdlbao-cao-nuoi-trong-detail.component.css']
})
export class GSDLBaoCaoNuoiTrongDetailComponent implements OnInit {

  constructor(
    public dialogRef: MatDialogRef<GSDLBaoCaoNuoiTrongDetailComponent>,
    @Inject(MAT_DIALOG_DATA) public data: any,

    public NotificationService: NotificationService,
        
    public GSDLBaoCaoNuoiTrongService: GSDLBaoCaoNuoiTrongService,
  ) { }

  ngOnInit(): void {    
  }

  

  GSDLBaoCaoNuoiTrongSave() {
    this.GSDLBaoCaoNuoiTrongService.IsShowLoading = true;
    this.GSDLBaoCaoNuoiTrongService.SaveAsync().subscribe(
      res => {
        this.GSDLBaoCaoNuoiTrongService.FormData = res as GSDLBaoCaoNuoiTrong;        
        this.NotificationService.warn(environment.SaveSuccess);
        this.GSDLBaoCaoNuoiTrongService.IsShowLoading = false;
      },
      err => {
        this.NotificationService.warn(environment.SaveNotSuccess);
        this.GSDLBaoCaoNuoiTrongService.IsShowLoading = false;
      }
    );
  }
  Close() {
    this.dialogRef.close();
  }

}