import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { PackOtherDocument } from 'src/app/shared/PackOtherDocument.model';
import { PackOtherDocumentService } from 'src/app/shared/PackOtherDocument.service';
@Component({
  selector: 'app-pack-other-document',
  templateUrl: './pack-other-document.component.html',
  styleUrls: ['./pack-other-document.component.css']
})
export class PackOtherDocumentComponent implements OnInit {
  @ViewChild('PackOtherDocumentSort') PackOtherDocumentSort: MatSort;
  @ViewChild('PackOtherDocumentPaginator') PackOtherDocumentPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public PackOtherDocumentService: PackOtherDocumentService,
  ) { }

  ngOnInit(): void {
  }

  PackOtherDocumentSearch() {
    this.PackOtherDocumentService.SearchAll(this.PackOtherDocumentSort, this.PackOtherDocumentPaginator);
  }
  PackOtherDocumentSave(element: PackOtherDocument) {
    this.PackOtherDocumentService.FormData = element;
    this.NotificationService.warn(this.PackOtherDocumentService.ComponentSaveAll(this.PackOtherDocumentSort, this.PackOtherDocumentPaginator));
  }
  PackOtherDocumentDelete(element: PackOtherDocument) {
    this.PackOtherDocumentService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.PackOtherDocumentService.ComponentDeleteAll(this.PackOtherDocumentSort, this.PackOtherDocumentPaginator));
  }


}
