
import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { ChuoiCungUngProductGroups } from 'src/app/shared/ChuoiCungUngProductGroups.model';
import { ChuoiCungUngProductGroupsService } from 'src/app/shared/ChuoiCungUngProductGroups.service';
@Component({
  selector: 'app-chuoi-cung-ung-product-groups',
  templateUrl: './chuoi-cung-ung-product-groups.component.html',
  styleUrls: ['./chuoi-cung-ung-product-groups.component.css']
})
export class ChuoiCungUngProductGroupsComponent implements OnInit {

  @ViewChild('ChuoiCungUngProductGroupsSort') ChuoiCungUngProductGroupsSort: MatSort;
  @ViewChild('ChuoiCungUngProductGroupsPaginator') ChuoiCungUngProductGroupsPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public ChuoiCungUngProductGroupsService: ChuoiCungUngProductGroupsService,
  ) { }

  ngOnInit(): void {
  }

  ChuoiCungUngProductGroupsSearch() {
    this.ChuoiCungUngProductGroupsService.SearchAll(this.ChuoiCungUngProductGroupsSort, this.ChuoiCungUngProductGroupsPaginator);
  }
  ChuoiCungUngProductGroupsSave(element: ChuoiCungUngProductGroups) {
    this.ChuoiCungUngProductGroupsService.FormData = element;
    this.NotificationService.warn(this.ChuoiCungUngProductGroupsService.ComponentSaveAll(this.ChuoiCungUngProductGroupsSort, this.ChuoiCungUngProductGroupsPaginator));
  }
  ChuoiCungUngProductGroupsDelete(element: ChuoiCungUngProductGroups) {
    this.ChuoiCungUngProductGroupsService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.ChuoiCungUngProductGroupsService.ComponentDeleteAll(this.ChuoiCungUngProductGroupsSort, this.ChuoiCungUngProductGroupsPaginator));
  }


}
