
import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { BienBanMSVT } from 'src/app/shared/BienBanMSVT.model';
import { BienBanMSVTService } from 'src/app/shared/BienBanMSVT.service';
@Component({
  selector: 'app-bien-ban-msvt',
  templateUrl: './bien-ban-msvt.component.html',
  styleUrls: ['./bien-ban-msvt.component.css']
})
export class BienBanMSVTComponent implements OnInit {
  @ViewChild('BienBanMSVTSort') BienBanMSVTSort: MatSort;
  @ViewChild('BienBanMSVTPaginator') BienBanMSVTPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public BienBanMSVTService: BienBanMSVTService,
  ) { }

  ngOnInit(): void {
  }

  BienBanMSVTSearch() {
    this.BienBanMSVTService.SearchAll(this.BienBanMSVTSort, this.BienBanMSVTPaginator);
  }
  BienBanMSVTSave(element: BienBanMSVT) {
    this.BienBanMSVTService.FormData = element;
    this.NotificationService.warn(this.BienBanMSVTService.ComponentSaveAll(this.BienBanMSVTSort, this.BienBanMSVTPaginator));
  }
  BienBanMSVTDelete(element: BienBanMSVT) {
    this.BienBanMSVTService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.BienBanMSVTService.ComponentDeleteAll(this.BienBanMSVTSort, this.BienBanMSVTPaginator));
  }


}
