import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { PackingRegisterMarkets } from 'src/app/shared/PackingRegisterMarkets.model';
import { PackingRegisterMarketsService } from 'src/app/shared/PackingRegisterMarkets.service';
@Component({
  selector: 'app-packing-register-markets',
  templateUrl: './packing-register-markets.component.html',
  styleUrls: ['./packing-register-markets.component.css']
})
export class PackingRegisterMarketsComponent implements OnInit {
  @ViewChild('PackingRegisterMarketsSort') PackingRegisterMarketsSort: MatSort;
  @ViewChild('PackingRegisterMarketsPaginator') PackingRegisterMarketsPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public PackingRegisterMarketsService: PackingRegisterMarketsService,
  ) { }

  ngOnInit(): void {
  }

  PackingRegisterMarketsSearch() {
    this.PackingRegisterMarketsService.SearchAll(this.PackingRegisterMarketsSort, this.PackingRegisterMarketsPaginator);
  }
  PackingRegisterMarketsSave(element: PackingRegisterMarkets) {
    this.PackingRegisterMarketsService.FormData = element;
    this.NotificationService.warn(this.PackingRegisterMarketsService.ComponentSaveAll(this.PackingRegisterMarketsSort, this.PackingRegisterMarketsPaginator));
  }
  PackingRegisterMarketsDelete(element: PackingRegisterMarkets) {
    this.PackingRegisterMarketsService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.PackingRegisterMarketsService.ComponentDeleteAll(this.PackingRegisterMarketsSort, this.PackingRegisterMarketsPaginator));
  }


}
