import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { ChuoiCungUng } from 'src/app/shared/ChuoiCungUng.model';
import { ChuoiCungUngService } from 'src/app/shared/ChuoiCungUng.service';
@Component({
  selector: 'app-chuoi-cung-ung',
  templateUrl: './chuoi-cung-ung.component.html',
  styleUrls: ['./chuoi-cung-ung.component.css']
})
export class ChuoiCungUngComponent implements OnInit {


  @ViewChild('ChuoiCungUngSort') ChuoiCungUngSort: MatSort;
  @ViewChild('ChuoiCungUngPaginator') ChuoiCungUngPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public ChuoiCungUngService: ChuoiCungUngService,
  ) { }

  ngOnInit(): void {
  }

  ChuoiCungUngSearch() {
    this.ChuoiCungUngService.SearchAll(this.ChuoiCungUngSort, this.ChuoiCungUngPaginator);
  }
  ChuoiCungUngSave(element: ChuoiCungUng) {
    this.ChuoiCungUngService.FormData = element;
    this.NotificationService.warn(this.ChuoiCungUngService.ComponentSaveAll(this.ChuoiCungUngSort, this.ChuoiCungUngPaginator));
  }
  ChuoiCungUngDelete(element: ChuoiCungUng) {
    this.ChuoiCungUngService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.ChuoiCungUngService.ComponentDeleteAll(this.ChuoiCungUngSort, this.ChuoiCungUngPaginator));
  }


}
