
import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { BienBanCSDG } from 'src/app/shared/BienBanCSDG.model';
import { BienBanCSDGService } from 'src/app/shared/BienBanCSDG.service';
@Component({
  selector: 'app-bien-ban-csdg',
  templateUrl: './bien-ban-csdg.component.html',
  styleUrls: ['./bien-ban-csdg.component.css']
})
export class BienBanCSDGComponent implements OnInit {

  @ViewChild('BienBanCSDGSort') BienBanCSDGSort: MatSort;
  @ViewChild('BienBanCSDGPaginator') BienBanCSDGPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public BienBanCSDGService: BienBanCSDGService,
  ) { }

  ngOnInit(): void {
  }

  BienBanCSDGSearch() {
    this.BienBanCSDGService.SearchAll(this.BienBanCSDGSort, this.BienBanCSDGPaginator);
  }
  BienBanCSDGSave(element: BienBanCSDG) {
    this.BienBanCSDGService.FormData = element;
    this.NotificationService.warn(this.BienBanCSDGService.ComponentSaveAll(this.BienBanCSDGSort, this.BienBanCSDGPaginator));
  }
  BienBanCSDGDelete(element: BienBanCSDG) {
    this.BienBanCSDGService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.BienBanCSDGService.ComponentDeleteAll(this.BienBanCSDGSort, this.BienBanCSDGPaginator));
  }


}
