import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { PackingDocument } from 'src/app/shared/PackingDocument.model';
import { PackingDocumentService } from 'src/app/shared/PackingDocument.service';
@Component({
  selector: 'app-packing-document',
  templateUrl: './packing-document.component.html',
  styleUrls: ['./packing-document.component.css']
})
export class PackingDocumentComponent implements OnInit {

  @ViewChild('PackingDocumentSort') PackingDocumentSort: MatSort;
  @ViewChild('PackingDocumentPaginator') PackingDocumentPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public PackingDocumentService: PackingDocumentService,
  ) { }

  ngOnInit(): void {
  }

  PackingDocumentSearch() {
    this.PackingDocumentService.SearchAll(this.PackingDocumentSort, this.PackingDocumentPaginator);
  }
  PackingDocumentSave(element: PackingDocument) {
    this.PackingDocumentService.FormData = element;
    this.NotificationService.warn(this.PackingDocumentService.ComponentSaveAll(this.PackingDocumentSort, this.PackingDocumentPaginator));
  }
  PackingDocumentDelete(element: PackingDocument) {
    this.PackingDocumentService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.PackingDocumentService.ComponentDeleteAll(this.PackingDocumentSort, this.PackingDocumentPaginator));
  }


}
