import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { Certificate } from 'src/app/shared/Certificate.model';
import { CertificateService } from 'src/app/shared/Certificate.service';
@Component({
  selector: 'app-certificate',
  templateUrl: './certificate.component.html',
  styleUrls: ['./certificate.component.css']
})
export class CertificateComponent implements OnInit {


  @ViewChild('CertificateSort') CertificateSort: MatSort;
  @ViewChild('CertificatePaginator') CertificatePaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public CertificateService: CertificateService,
  ) { }

  ngOnInit(): void {
  }

  CertificateSearch() {
    this.CertificateService.SearchAll(this.CertificateSort, this.CertificatePaginator);
  }
  CertificateSave(element: Certificate) {
    this.CertificateService.FormData = element;
    this.NotificationService.warn(this.CertificateService.ComponentSaveAll(this.CertificateSort, this.CertificatePaginator));
  }
  CertificateDelete(element: Certificate) {
    this.CertificateService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.CertificateService.ComponentDeleteAll(this.CertificateSort, this.CertificatePaginator));
  }


}
