import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { MarketPlace } from 'src/app/shared/MarketPlace.model';
import { MarketPlaceService } from 'src/app/shared/MarketPlace.service';
@Component({
  selector: 'app-market-place',
  templateUrl: './market-place.component.html',
  styleUrls: ['./market-place.component.css']
})
export class MarketPlaceComponent implements OnInit {

  @ViewChild('MarketPlaceSort') MarketPlaceSort: MatSort;
  @ViewChild('MarketPlacePaginator') MarketPlacePaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public MarketPlaceService: MarketPlaceService,
  ) { }

  ngOnInit(): void {
  }

  MarketPlaceSearch() {
    this.MarketPlaceService.SearchAll(this.MarketPlaceSort, this.MarketPlacePaginator);
  }
  MarketPlaceSave(element: MarketPlace) {
    this.MarketPlaceService.FormData = element;
    this.NotificationService.warn(this.MarketPlaceService.ComponentSaveAll(this.MarketPlaceSort, this.MarketPlacePaginator));
  }
  MarketPlaceDelete(element: MarketPlace) {
    this.MarketPlaceService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.MarketPlaceService.ComponentDeleteAll(this.MarketPlaceSort, this.MarketPlacePaginator));
  }


}
