
import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';

import { VerifyEmailOtp } from 'src/app/shared/VerifyEmailOtp.model';
import { VerifyEmailOtpService } from 'src/app/shared/VerifyEmailOtp.service';

@Component({
  selector: 'app-verify-email-otp',
  templateUrl: './verify-email-otp.component.html',
  styleUrls: ['./verify-email-otp.component.css']
})
export class VerifyEmailOtpComponent implements OnInit {
  @ViewChild('VerifyEmailOtpSort') VerifyEmailOtpSort: MatSort;
  @ViewChild('VerifyEmailOtpPaginator') VerifyEmailOtpPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public VerifyEmailOtpService: VerifyEmailOtpService,
  ) { }

  ngOnInit(): void {
  }

  VerifyEmailOtpSearch() {
    this.VerifyEmailOtpService.SearchAll(this.VerifyEmailOtpSort, this.VerifyEmailOtpPaginator);
  }
  VerifyEmailOtpSave(element: VerifyEmailOtp) {
    this.VerifyEmailOtpService.FormData = element;
    this.NotificationService.warn(this.VerifyEmailOtpService.ComponentSaveAll(this.VerifyEmailOtpSort, this.VerifyEmailOtpPaginator));
  }
  VerifyEmailOtpDelete(element: VerifyEmailOtp) {
    this.VerifyEmailOtpService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.VerifyEmailOtpService.ComponentDeleteAll(this.VerifyEmailOtpSort, this.VerifyEmailOtpPaginator));
  }
}
