import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { PucInfo } from 'src/app/shared/PucInfo.model';
import { PucInfoService } from 'src/app/shared/PucInfo.service';
@Component({
  selector: 'app-puc-info',
  templateUrl: './puc-info.component.html',
  styleUrls: ['./puc-info.component.css']
})
export class PucInfoComponent implements OnInit {

  @ViewChild('PucInfoSort') PucInfoSort: MatSort;
  @ViewChild('PucInfoPaginator') PucInfoPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public PucInfoService: PucInfoService,
  ) { }

  ngOnInit(): void {
  }

  PucInfoSearch() {
    this.PucInfoService.SearchAll(this.PucInfoSort, this.PucInfoPaginator);
  }
  PucInfoSave(element: PucInfo) {
    this.PucInfoService.FormData = element;
    this.NotificationService.warn(this.PucInfoService.ComponentSaveAll(this.PucInfoSort, this.PucInfoPaginator));
  }
  PucInfoDelete(element: PucInfo) {
    this.PucInfoService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.PucInfoService.ComponentDeleteAll(this.PucInfoSort, this.PucInfoPaginator));
  }


}
