import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';
import { KiemTraTapChatBienBan } from 'src/app/shared/KiemTraTapChatBienBan.model';
import { KiemTraTapChatBienBanService } from 'src/app/shared/KiemTraTapChatBienBan.service';
@Component({
  selector: 'app-kiem-tra-tap-chat-bien-ban',
  templateUrl: './kiem-tra-tap-chat-bien-ban.component.html',
  styleUrls: ['./kiem-tra-tap-chat-bien-ban.component.css']
})
export class KiemTraTapChatBienBanComponent implements OnInit {

  @ViewChild('KiemTraTapChatBienBanSort') KiemTraTapChatBienBanSort: MatSort;
  @ViewChild('KiemTraTapChatBienBanPaginator') KiemTraTapChatBienBanPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public KiemTraTapChatBienBanService: KiemTraTapChatBienBanService,
  ) { }

  ngOnInit(): void {
  }

  KiemTraTapChatBienBanSearch() {
    this.KiemTraTapChatBienBanService.SearchAll(this.KiemTraTapChatBienBanSort, this.KiemTraTapChatBienBanPaginator);
  }
  KiemTraTapChatBienBanSave(element: KiemTraTapChatBienBan) {
    this.KiemTraTapChatBienBanService.FormData = element;
    this.NotificationService.warn(this.KiemTraTapChatBienBanService.ComponentSaveAll(this.KiemTraTapChatBienBanSort, this.KiemTraTapChatBienBanPaginator));
  }
  KiemTraTapChatBienBanDelete(element: KiemTraTapChatBienBan) {
    this.KiemTraTapChatBienBanService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.KiemTraTapChatBienBanService.ComponentDeleteAll(this.KiemTraTapChatBienBanSort, this.KiemTraTapChatBienBanPaginator));
  }


}
