import { Component, OnInit, ViewChild } from '@angular/core';
import { MatDialog, MatDialogConfig } from '@angular/material/dialog';
import { environment } from 'src/environments/environment';
import { NotificationService } from 'src/app/shared/Notification.service';
import { MatTableDataSource } from '@angular/material/table';
import { MatSort } from '@angular/material/sort';
import { MatPaginator } from '@angular/material/paginator';

import { ThamDinhCompanyProductGroups } from 'src/app/shared/ThamDinhCompanyProductGroups.model';
import { ThamDinhCompanyProductGroupsService } from 'src/app/shared/ThamDinhCompanyProductGroups.service';
@Component({
  selector: 'app-tham-dinh-company-product-groups',
  templateUrl: './tham-dinh-company-product-groups.component.html',
  styleUrls: ['./tham-dinh-company-product-groups.component.css']
})

export class ThamDinhCompanyProductGroupsComponent implements OnInit {
  @ViewChild('ThamDinhCompanyProductGroupsSort') ThamDinhCompanyProductGroupsSort: MatSort;
  @ViewChild('ThamDinhCompanyProductGroupsPaginator') ThamDinhCompanyProductGroupsPaginator: MatPaginator;

  constructor(
    private dialog: MatDialog,
    public NotificationService: NotificationService,

    public ThamDinhCompanyProductGroupsService: ThamDinhCompanyProductGroupsService,
  ) { }

  ngOnInit(): void {
  }

  ThamDinhCompanyProductGroupsSearch() {
    this.ThamDinhCompanyProductGroupsService.SearchAll(this.ThamDinhCompanyProductGroupsSort, this.ThamDinhCompanyProductGroupsPaginator);
  }
  ThamDinhCompanyProductGroupsSave(element: ThamDinhCompanyProductGroups) {
    this.ThamDinhCompanyProductGroupsService.FormData = element;
    this.NotificationService.warn(this.ThamDinhCompanyProductGroupsService.ComponentSaveAll(this.ThamDinhCompanyProductGroupsSort, this.ThamDinhCompanyProductGroupsPaginator));
  }
  ThamDinhCompanyProductGroupsDelete(element: ThamDinhCompanyProductGroups) {
    this.ThamDinhCompanyProductGroupsService.BaseParameter.ID = element.ID;
    this.NotificationService.warn(this.ThamDinhCompanyProductGroupsService.ComponentDeleteAll(this.ThamDinhCompanyProductGroupsSort, this.ThamDinhCompanyProductGroupsPaginator));
  }
}
